import type { FilterDataStructure, Option } from 'models/Filters';

import { PERFORMANCE_AND_BREAKDOWN_BRANDS } from './assets/brandImageUrls';

type LocalFilterCatalog = {
  brandOptionsByCountry: Record<string, Option[]>;
  subBrandOptionsByBrand: Record<string, Option[]>;
  skuOptionsBySubBrand: Record<string, Option[]>;
};

const brand = (
  value: string,
  imageKey: keyof typeof PERFORMANCE_AND_BREAKDOWN_BRANDS,
): Option => ({
  value,
  label: value,
  image_url: PERFORMANCE_AND_BREAKDOWN_BRANDS[imageKey],
});

const BRA_BRANDS: Option[] = [
  brand('Brahma', 'brahma'),
  brand('Skol', 'skol'),
  brand('Stella Artois', 'stella_artois'),
  brand('Budweiser', 'budweiser'),
  brand('Corona', 'corona'),
];

const USA_BRANDS: Option[] = [
  brand('Budweiser', 'budweiser'),
  brand('Bud Light', 'bud_light'),
  brand('Busch', 'busch'),
  brand('Michelob', 'michelob'),
];

const MEX_BRANDS: Option[] = [
  brand('Corona', 'corona'),
  brand('Modelo', 'modelo'),
  brand('Victoria', 'victoria'),
  brand('Michelob', 'michelob'),
];

const COL_BRANDS: Option[] = [
  brand('Aguila', 'aguila'),
  brand('Pilsen', 'pilsen'),
  brand('Budweiser', 'budweiser'),
  brand('Corona', 'corona'),
];

const ARG_BRANDS: Option[] = [
  brand('Quilmes', 'pilsen'),
  brand('Stella Artois', 'stella_artois'),
  brand('Brahma', 'brahma'),
  brand('Corona', 'corona'),
];

const BEL_BRANDS: Option[] = [
  brand('Stella Artois', 'stella_artois'),
  brand('Budweiser', 'budweiser'),
  brand('Corona', 'corona'),
  brand('Leffe', 'stella_artois'),
];

const DEFAULT_COUNTRY_BRANDS: Option[] = [
  brand('Budweiser', 'budweiser'),
  brand('Corona', 'corona'),
  brand('Stella Artois', 'stella_artois'),
  brand('Skol', 'skol'),
];

const BRAHMA_SUB_BRANDS: Option[] = [
  { value: 'Brahma', label: 'Brahma' },
  { value: 'Brahma - NA', label: 'Brahma - NA' },
  { value: 'Brahma Duplo Malte', label: 'Brahma Duplo Malte' },
  { value: 'Brahma Extra', label: 'Brahma Extra' },
  { value: 'Brahma Chopp', label: 'Brahma Chopp' },
  { value: 'Brahma - Others', label: 'Brahma - Others' },
];

const DUPLO_MALTE_SKUS: Option[] = [
  {
    value: 'Brahma Duplo Malte bottle 000ml',
    label: 'Brahma Duplo Malte bottle 000ml',
  },
  {
    value: 'Brahma Duplo Malte long neck 000ml',
    label: 'Brahma Duplo Malte long neck 000ml',
  },
  {
    value: 'Brahma Duplo Malte can 000ml',
    label: 'Brahma Duplo Malte can 000ml',
  },
  {
    value: 'Brahma Duplo Malte bottle 600ml',
    label: 'Brahma Duplo Malte bottle 600ml',
  },
];

const BRAHMA_CHOPP_SKUS: Option[] = [
  { value: 'Brahma Chopp bottle 350ml', label: 'Brahma Chopp bottle 350ml' },
  {
    value: 'Brahma Chopp long neck 473ml',
    label: 'Brahma Chopp long neck 473ml',
  },
  { value: 'Brahma Chopp can 473ml', label: 'Brahma Chopp can 473ml' },
];

const PERFORMANCE_AND_BREAKDOWN_LOCAL_FILTER_CATALOG: LocalFilterCatalog = {
  brandOptionsByCountry: {
    USA: USA_BRANDS,
    BRA: BRA_BRANDS,
    MEX: MEX_BRANDS,
    CHN: DEFAULT_COUNTRY_BRANDS,
    COL: COL_BRANDS,
    ZAF: DEFAULT_COUNTRY_BRANDS,
    ARG: ARG_BRANDS,
    BOL: DEFAULT_COUNTRY_BRANDS,
    KOR: DEFAULT_COUNTRY_BRANDS,
    PER: DEFAULT_COUNTRY_BRANDS,
    BEL: BEL_BRANDS,
    FRA: DEFAULT_COUNTRY_BRANDS,
  },
  subBrandOptionsByBrand: {
    Brahma: BRAHMA_SUB_BRANDS,
  },
  skuOptionsBySubBrand: {
    'Brahma Duplo Malte': DUPLO_MALTE_SKUS,
    'Brahma Chopp': BRAHMA_CHOPP_SKUS,
  },
};

function buildFilterDataPatch(
  catalog: LocalFilterCatalog,
): Pick<FilterDataStructure, 'brands' | 'sku'> {
  const brandValues: Record<
    string,
    {
      brands: Array<{
        value: string;
        label: string;
        sub_brands: Option[];
        default: Option;
        image_url?: string;
      }>;
      default: Option;
    }
  > = {};

  for (const [countryCode, brandOptions] of Object.entries(
    catalog.brandOptionsByCountry,
  )) {
    const brands = brandOptions.map((option) => {
      const subBrands =
        catalog.subBrandOptionsByBrand[String(option.value)] ?? [];

      return {
        value: String(option.value),
        label: String(option.label),
        sub_brands: subBrands,
        default: subBrands[0] ?? { value: 'All', label: 'All' },
        image_url: option.image_url,
      };
    });

    brandValues[countryCode] = {
      brands,
      default: brandOptions[0] ?? { value: 'All', label: 'All' },
    };
  }

  const skuValues: Record<string, Option[]> = {};

  for (const [brandId, subBrands] of Object.entries(
    catalog.subBrandOptionsByBrand,
  )) {
    const brandSkus = subBrands.flatMap(
      (subBrand) => catalog.skuOptionsBySubBrand[String(subBrand.value)] ?? [],
    );

    if (brandSkus.length > 0) {
      skuValues[brandId] = brandSkus;
    }
  }

  return {
    brands: {
      values: brandValues,
      default: null,
      enabled: true,
    },
    sku: {
      values: skuValues,
      default: null,
      enabled: true,
    },
  };
}

export const PERFORMANCE_AND_BREAKDOWN_FILTER_CATALOG_PATCH =
  buildFilterDataPatch(PERFORMANCE_AND_BREAKDOWN_LOCAL_FILTER_CATALOG);
